"""The server's JSON, typed: ``ui/web/src/api/afk.gen.ts`` is generated by
the server's ``scripts/dev/gen_page_ts.py`` from its ``web/types.py``, so it can only be checked where
the server's source is at hand. Here: when ``the server`` is importable from a source checkout,
regenerate it and compare. The page's own CI does not install the server, so there this skips;
the server's tests (the routes answer their types) and the release's e2e hold the other side.
The page itself checks the number: the server's ``/api/status`` answers ``host_api``, and the
list's head says so when it is not ``HOST_API_VERSION`` (``lib/hostapi.ts``)."""
import re
import subprocess
import sys
from pathlib import Path

from .webui import src

GEN = Path(__file__).resolve().parents[2] / "src" / "kranto" / "page" / "ui" / "web" / "src" / "api" / "afk.gen.ts"


def _kranto_script() -> Path:
    return Path(__file__).resolve().parents[2] / "scripts" / "gen_ts.py"


def test_afk_gen_ts_is_what_kranto_generates(tmp_path):
    script = _kranto_script()
    out = tmp_path / "afk.gen.ts"
    p = subprocess.run([sys.executable, str(script), str(out)], capture_output=True, text=True,
                       timeout=120)
    assert p.returncode == 0, p.stderr
    assert out.read_text() == GEN.read_text(), (
        f"stale: run {script} {GEN} with the server's venv")


def test_afk_gen_ts_says_where_it_comes_from_and_its_version():
    text = GEN.read_text()
    assert text.startswith("// Generated from the server's web/types.py; do not edit")
    assert re.search(r"^export const HOST_API_VERSION = \d+;$", text, re.M)
    assert '  "/api/health": Health;' in text and "  host_api: number;" in text


def test_the_page_compares_krantos_api_version():
    hostapi = src("lib/hostapi.ts")
    assert 'import { HOST_API_VERSION } from "../api/afk.gen";' in hostapi
    assert "update both with kranto update." in hostapi
    assert "hostApiLine(" in src("shell/ListHead.svelte")
    # Settings › System › Health reads the server's JSON through the generated types
    assert 'from "../../api/afk.gen"' in src("pages/settings/health.ts")
